from pathlib import Path
import json,hashlib
ROOT=Path(__file__).resolve().parents[4]
BASE=Path(__file__).resolve().parent
DATE='2026-10-29'
def read(p):return json.loads(p.read_text())
def write(p,d):p.write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n')
caps=read(BASE/'capture-manifest.json')['records'];by={x['candidate_id']:x for x in caps}
base=dict(accessed_on=DATE,sample_size=None,fieldwork_period=None,method_available=True,funding_or_commercial_interest='Official guidance, not supplier marketing or an employer-priority survey',review_status='relevant_original_html_sections_inspected',reuse_status='Private verification; final-use wording, rights and applicability review pending')
rows=[]
for ident,title,pub,typ,published,updated,loc,pop,lim in [
 ('CTX7-S01','Holiday pay and entitlement reforms from 1 January 2024','Department for Business and Trade','official_working_arrangement_and_applicability_guidance',None,'2024-04-01','Introduction caveat; sections1–2 definitions;3.1 applicability and6.2 eligible alternative method','Guidance on specific working arrangements and leave-year conditions under its stated Working Time context','Mechanism/context evidence, not a survey of sector priorities, prevalence or observed employer funding. No worker-specific classification, entitlement/rate calculation, advice on contractual change or assumption of complete current territorial/legal coverage. Illustrative percentages/hours and monetary examples not transferred.'),
 ('CTX7-S02','Employees working abroad','HM Revenue & Customs','official_cross_border_payroll_context_guidance','2014-06-12','2026-07-07','Introduction; How to calculate PAYE Income Tax; National Insurance subsections; Operating separate payrolls','UK employer PAYE/NI guidance for employees working abroad; source-specific territory/duration/coverage context','Official mechanism, not empirical evidence of global-company priority or budget. No individual tax/social-security determination, country eligibility list, treaty advice, numeric duration rule or country-count complexity ranking is transferred. Actual applicability remains case-specific.')]:
 c=by[ident];rows.append(dict(base,candidate_id=ident,title=title,publisher=pub,url=c['url'],source_type=typ,published_date=published,updated_date=updated,date_note='Displayed original/substantive-update dates, where established; access date is not a new outcome or rule date.',locator=loc,population=pop,limitations=lim,capture_path=c['path'],capture_sha256=c['sha256'],capture_kind='retained_original_html',text_path=c['text_path'],text_sha256=c['text_sha256']))
sources=read(ROOT/'02-evidence/registers/sources.json')['records'];west=next(x for x in sources if x['source_id']=='SRC-0198');bc=by['SRC-0107']
reuses=[dict(source_id='SRC-0107',url=bc['url'],locator='Opening eligibility statement; What it does and agent/bookkeeper limitation; Before you start',review_result='Tool eligibility/own-employer scope is bounded, not a payroll-complexity scale or observed priority difference between small and large firms.',capture_path=bc['path'],capture_sha256=bc['sha256'],text_path=bc['text_path'],text_sha256=bc['text_sha256']),dict(source_id='SRC-0198',url=west['url'],locator='Official10March2026 body, revised timing and school/term-time users',review_result='An employer-stated calendar/user context affects its reported rollout timing. One programme, not evidence of sector-wide priorities, optimal timing or causal risk reduction.',capture_path=west['capture_path'],capture_sha256=west['capture_sha256'],text_path=west['candidate_detail']['text_path'],text_sha256=west['candidate_detail']['text_sha256'])]
write(BASE/'source-candidates.json',dict(date=DATE,records=rows,reused_canonical_sources=reuses,independent_empirical_datasets=0))
cs=[
 ('CTX7-C01',['CTX7-S01'],'The holiday-pay guidance makes working-arrangement classification depend on the specific contractual pattern, and distinguishes the applicability of named methods by worker type and leave year. A sector or headcount label does not supply those facts.','official_conditional_workforce_context','Introduction; sections1–2 and3.1; method application, not rate calculation','No individual worker classification, employment-law conclusion, calculation or inference that a whole sector uses one method. The guidance itself is not definitive advice for each case.'),
 ('CTX7-C02',['CTX7-S02'],'HMRC’s cross-border payroll guidance distinguishes work territory, expected duration and coverage circumstances; it treats Income Tax, National Insurance and separate payroll-scheme administration as distinct considerations.','official_conditional_jurisdiction_context','Introduction; PAYE Income Tax and National Insurance headings; Operating separate payrolls','No tax/treaty determination or claim that country count alone predicts complexity, investment need, funding or outsourcing. Country/threshold examples are not adopted.'),
 ('CTX7-C03',['SRC-0107'],'Basic PAYE Tools has a bounded own-employer eligibility and task scope and is not designed for agents/bookkeepers. This is an option boundary, not evidence that all smaller payrolls are simple or share a common investment priority.','official_product_scope_boundary','Opening eligibility; What it does; Before you start','No application trial, customer suitability, free whole-life payroll operation, employer-size priority difference or complexity threshold inferred.'),
 ('CTX7-C04',['SRC-0198'],'West Sussex’s March2026 employer communication links its revised HR/payroll rollout timing to scale, safe reliable payroll and the schools/term-time user context.','employer_reported_context_and_timing','Official10March2026 body, retainedtext30–32','One employer-stated reason, not education-sector prevalence, comparative sector priority, an optimal migration season, measured benefit or a new independent employer case.'),
 ('CTX7-C05',['CTX7-S01','CTX7-S02','SRC-0107','SRC-0198'],'R07 should record relevant dimensions of context separately: the payroll population in the contributor’s remit, working/pay arrangements, applicable jurisdictions, retained delivery tasks and the decision/change stage. Context can explain a plausible mechanism without establishing a between-group priority difference.','researcher_analytical_application','Cross-source application of conditional workforce/jurisdiction, option-scope and dated employer context; instrumentQ002/Q005 remains the core basis','Optional selective interpretation, not additional mandatory fields, employer quotas, validated segmentation, complexity score or causal subgroup conclusion. Headquarters, total global workforce and payroll population are not assumed interchangeable; sparse or missing groups cannot be filled from public examples.')]
claims=[]
for ident,srcs,txt,cl,loc,lim in cs:
 claims.append(dict(candidate_id=ident,source_ids=srcs,claim_text=txt,evidence_class=cl,locator=loc,limitations=lim,review_mode='Relevant original HTML guidance inspected and retained; West Sussex is an explicitly dated canonical employer-communication reuse, not independently evaluated outcome evidence',population='Source-specific guidance or single-employer stated context; analyst application separate',value=None,unit=None,time_period='Source-specific applicability and event dates; no longitudinal or subgroup estimate'))
write(BASE/'claim-candidates.json',dict(date=DATE,records=claims))
write(BASE/'search-review-log.json',dict(date=DATE,purpose='Distinguish contextual mechanism and option eligibility from demonstrated between-group priorities',queries=['site.gov.uk holiday pay irregular hours part-year guidance','site.gov.uk PAYE employees working abroad territory duration','Original source review Basic PAYE Tools own-employer eligibility and task limits','Re-read West Sussex10March2026 rollout rationale'],inspected_routes=[x['url'] for x in rows+reuses],selection_rationale='Two conditional official mechanisms and two bounded canonical scope/employer examples are sufficient for this strand. No country/sector ranking or additional survey is manufactured.',excluded=['Secondary news/adviser tax advice and forum anecdotes','Specific rates, example hours, country lists and duration thresholds','Statistical SME/large or country-group difference without comparable item bases and method','Treating a public-authority example as a representative sector, or separate documents as new employers'],external_actions=[]))
checked=[]
for c in caps:
 for pathkey,hashkey in [('path','sha256'),('text_path','text_sha256')]:
  q=ROOT/c[pathkey];assert hashlib.sha256(q.read_bytes()).hexdigest()==c[hashkey];checked.append(dict(path=c[pathkey],sha256=c[hashkey],passed=True))
for c in reuses:
 for pathkey,hashkey in [('capture_path','capture_sha256'),('text_path','text_sha256')]:
  q=ROOT/c[pathkey];assert hashlib.sha256(q.read_bytes()).hexdigest()==c[hashkey]
write(BASE/'verification.json',dict(date=DATE,status='passed',new_source_candidates=2,reused_routes=2,claim_records=5,original_files_checked=len(checked),checks=checked,no_numerical_estimates=True,no_external_actions=True))
print('Context candidates ready:2 new,2 reused,5 bounded claims;6 current original/text hashes checked; reused originals/text also verified')
